// @humid/pass/atrest — the access pass at rest on the device.
//
// Between buying a pass and spending it there is no account yet, so no seed-derived
// key: the draft (the access code and the blinded request) and the finished pass used
// to sit in IndexedDB as they were. Now they are sealed under a per-install key:
//
//   install key   AES-GCM-256, generated by WebCrypto on first use as a NON-EXTRACTABLE
//                 CryptoKey and kept in its own IndexedDB database ("humid-keys"),
//                 apart from the pass ("humid" / wallet). The key's bytes are never
//                 visible to JavaScript: the WebView's crypto engine holds them and only
//                 ever encrypts or decrypts with them.
//   sealing       AES-GCM, fresh 96-bit IV per write, AAD "HUMID-PASS-v1", over the
//                 JSON of the whole wallet record (draft or ready).
//
// What this does: the code and the pass are no longer readable as stored, and a copy of
// the wallet record alone (a backup, a dump of one database) is useless without the
// key record from the same profile. What it does not do: the key is not in hardware.
// A copy of the WHOLE profile carries both the key and the pass, and an engine that
// serialises non-extractable keys to disk in the clear (Chromium, WebKit) leaves the
// key material in the profile's files. A native secret-store slot (Keychain, Keystore,
// DPAPI, Secret Service without a biometric) would close that; see docs/SECURITY.md.
//
// Older records (no `sealed` field) are re-sealed on the first read and the plaintext
// is overwritten. With no IndexedDB (a private window) the key lives in memory, like
// the pass itself does there.

const AAD = new TextEncoder().encode("HUMID-PASS-v1");
export const SEALED = "HUMID-PASS-v1";
const KEYS_DB = "humid-keys";
const KEYS_STORE = "keys";
const INSTALL = "install";

const subtle = () => globalThis.crypto?.subtle;

/* ---------------- the install key ---------------- */

function openKeysDb() {
  return new Promise((resolve) => {
    try {
      const req = indexedDB.open(KEYS_DB, 1);
      req.onupgradeneeded = () => { if (!req.result.objectStoreNames.contains(KEYS_STORE)) req.result.createObjectStore(KEYS_STORE); };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(null);
      req.onblocked = () => resolve(null);
    } catch { resolve(null); }
  });
}

const run = (db, mode, fn) => new Promise((resolve, reject) => {
  const tx = db.transaction(KEYS_STORE, mode);
  const req = fn(tx.objectStore(KEYS_STORE));
  tx.oncomplete = () => resolve(req?.result);
  tx.onerror = () => reject(tx.error);
  tx.onabort = () => reject(tx.error);
});

const newKey = () => subtle().generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);

let memoryKey = null;   // when IndexedDB is unavailable: this process only
let pending = null;     // one creation at a time

/**
 * This install's key. Created once, non-extractable, kept apart from the pass.
 * Two callers racing on first use get the same key: the second read wins over the
 * first write only if a key was already there.
 */
export async function installKey() {
  if (pending) return pending;
  pending = (async () => {
    if (typeof indexedDB === "undefined") return memoryKey ||= await newKey();
    const db = await openKeysDb();
    if (!db) return memoryKey ||= await newKey();
    try {
      let key = await run(db, "readonly", (o) => o.get(INSTALL));
      if (isAesKey(key)) return key;
      const fresh = await newKey();
      // add() fails if another context stored one in between; then take theirs
      try { await run(db, "readwrite", (o) => o.add(fresh, INSTALL)); key = fresh; }
      catch { key = await run(db, "readonly", (o) => o.get(INSTALL)); }
      if (!isAesKey(key)) throw new Error("install key unavailable");
      return key;
    } finally { db.close(); }
  })().finally(() => { pending = null; });
  return pending;
}

const isAesKey = (k) => !!k && typeof k === "object" && k.algorithm?.name === "AES-GCM" && k.extractable === false && typeof k.type === "string";

/** Drop the install key (tests). Nothing sealed under it opens again. */
export async function forgetInstallKey() {
  memoryKey = null;
  if (typeof indexedDB === "undefined") return;
  const db = await openKeysDb();
  if (!db) return;
  try { await run(db, "readwrite", (o) => o.delete(INSTALL)); } finally { db.close(); }
}

/* ---------------- sealing a wallet record ---------------- */

export async function sealRecord(key, record) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const pt = new TextEncoder().encode(JSON.stringify(record));
  const ct = new Uint8Array(await subtle().encrypt({ name: "AES-GCM", iv, additionalData: AAD }, key, pt));
  pt.fill(0);
  return { v: 1, sealed: SEALED, iv, ct };
}

export const isSealed = (stored) => !!stored && stored.sealed === SEALED && stored.iv instanceof Uint8Array && stored.ct instanceof Uint8Array;

export async function openRecord(key, stored) {
  if (!isSealed(stored)) throw new Error("not a sealed pass record");
  const pt = await subtle().decrypt({ name: "AES-GCM", iv: stored.iv, additionalData: AAD }, key, stored.ct);
  return JSON.parse(new TextDecoder().decode(pt));
}

/**
 * The wallet as the app uses it: the same get/put/clear as @humid/store's pass
 * methods, sealed under the install key. A record stored in the clear by an older
 * build is re-sealed on the first read and the plaintext overwritten.
 */
export function sealedWallet(store) {
  return {
    async get() {
      const stored = await store.getPass();
      if (!stored) return null;
      const key = await installKey();
      if (isSealed(stored)) {
        try { return await openRecord(key, stored); }
        catch { await store.clearPass(); return null; } // another install's key, or a damaged record: nothing to recover
      }
      // migration: a clear record from before sealing
      await store.putPass(await sealRecord(key, stored));
      return stored;
    },
    async put(record) { await store.putPass(await sealRecord(await installKey(), record)); },
    clear: () => store.clearPass(),
  };
}
